请对以下 case 进行三维加权评分。

=== case_id ===
Case-30-pet-feeder-009

=== 用户原始指令 (query.txt) ===
搞个卡片显示余粮比例，点一下跳app，底下显示已连接，喂完显示已完成

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个卡片显示余粮比例，点一下跳app，底下显示已连接，喂完显示已完成",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.clock",
        "abilityName": "com.huawei.hmos.clock.phone",
        "uri": ""
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "feeder": {
        "deviceName": {
          "type": "string",
          "description": "宠物喂食器设备名称，用于卡片标题。",
          "sampleValue": "宠物喂食器"
        },
        "food": {
          "percentValue": {
            "type": "number",
            "description": "当前余粮百分比数值，用于进度组件。",
            "sampleValue": 68
          },
          "percentText": {
            "type": "string",
            "description": "当前余粮比例展示文本。",
            "sampleValue": "68%"
          }
        },
        "connection": {
          "statusText": {
            "type": "string",
            "description": "设备连接状态展示文本。",
            "sampleValue": "已连接"
          }
        },
        "feeding": {
          "statusText": {
            "type": "string",
            "description": "最近一次喂食任务完成状态展示文本。",
            "sampleValue": "已完成"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/house_fill.svg",
      "description": "房屋实心图标，可表达智能家居设备入口和宠物喂食器所在家庭场景，适合放在浅色图标区中作为设备识别锚点。"
    }
  ]
}

